
const produtos = [
    {
            id: 1,
                    nome: "Smartphone Samsung",
                            preco: 1200,
                                    categoria: "Eletrônicos",
                                            imagem: "https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=500"
                                                },
                                                    {
                                                            id: 2,
                                                                    nome: "Notebook",
                                                                            preco: 2500,
                                                                                    categoria: "Eletrônicos",
                                                                                            imagem: "https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=500"
                                                                                                },
                                                                                                    {
                                                                                                            id: 3,
                                                                                                                    nome: "Camiseta Masculina",
                                                                                                                            preco: 59.90,
                                                                                                                                    categoria: "Roupas",
                                                                                                                                            imagem: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=500"
                                                                                                                                                },
                                                                                                                                                    {
                                                                                                                                                            id: 4,
                                                                                                                                                                    nome: "Tênis Esportivo",
                                                                                                                                                                            preco: 199.90,
                                                                                                                                                                                    categoria: "Calçados",
                                                                                                                                                                                            imagem: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=500"
                                                                                                                                                                                                },
                                                                                                                                                                                                    {
                                                                                                                                                                                                            id: 5,
                                                                                                                                                                                                                    nome: "Relógio Moderno",
                                                                                                                                                                                                                            preco: 150,
                                                                                                                                                                                                                                    categoria: "Acessórios",
                                                                                                                                                                                                                                            imagem: "https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=500"
                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                            id: 6,
                                                                                                                                                                                                                                                                    nome: "Fone Bluetooth",
                                                                                                                                                                                                                                                                            preco: 99.90,
                                                                                                                                                                                                                                                                                    categoria: "Eletrônicos",
                                                                                                                                                                                                                                                                                            imagem: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=500"
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                ];

                                                                                                                                                                                                                                                                                                let carrinho = [];
                                                                                                                                                                                                                                                                                                let categoriaAtual = "Todos";

                                                                                                                                                                                                                                                                                                function moeda(valor) {
                                                                                                                                                                                                                                                                                                    return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                            style: "currency",
                                                                                                                                                                                                                                                                                                                    currency: "BRL"
                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                        function mostrarProdutos(lista) {
                                                                                                                                                                                                                                                                                                                            const area = document.getElementById("produtos");

                                                                                                                                                                                                                                                                                                                                if (lista.length === 0) {
                                                                                                                                                                                                                                                                                                                                        area.innerHTML = "<p>Nenhum produto encontrado.</p>";
                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                        area.innerHTML = lista.map(p => `
                                                                                                                                                                                                                                                                                                                                                                <div class="card">
                                                                                                                                                                                                                                                                                                                                                                            <img src="${p.imagem}" alt="${p.nome}"
                                                                                                                                                                                                                                                                                                                                                                                             onerror="this.src='https://placehold.co/400x250?text=Produto'">

                                                                                                                                                                                                                                                                                                                                                                                                         <div class="info">
                                                                                                                                                                                                                                                                                                                                                                                                                         <h3>${p.nome}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                         <p class="preco">${moeda(p.preco)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                         <button onclick="adicionarCarrinho(${p.id})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             Adicionar ao carrinho
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     `).join("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function filtrar(categoria) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         categoriaAtual = categoria;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const lista = categoria === "Todos"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ? produtos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             : produtos.filter(p => p.categoria === categoria);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 mostrarProdutos(lista);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 function buscar() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const termo = document.getElementById("pesquisa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .value.toLowerCase().trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const lista = produtos.filter(p => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const categoriaCorreta =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     categoriaAtual === "Todos" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 p.categoria === categoriaAtual;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return categoriaCorreta &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     p.nome.toLowerCase().includes(termo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             mostrarProdutos(lista);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             document.getElementById("pesquisa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .addEventListener("input", buscar);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 function adicionarCarrinho(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const produto = produtos.find(p => p.id === id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!produto) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const item = carrinho.find(p => p.id === id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         item.quantidade++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     carrinho.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ...produto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             quantidade: 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 alert("Produto adicionado ao carrinho!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 function atualizarCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const area = document.getElementById("itensCarrinho");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         area.innerHTML = carrinho.length === 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ? "<p>Seu carrinho está vazio.</p>"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         : carrinho.map(p => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <div class="item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <strong>${p.nome}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <p>${p.quantidade} x ${moeda(p.preco)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <button onclick="removerItem(${p.id})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Remover
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const quantidade = carrinho.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 (soma, p) => soma + p.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const total = carrinho.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 (soma, p) => soma + p.preco * p.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         document.getElementById("quantidade").textContent = quantidade;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             document.getElementById("total").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     "Total: " + moeda(total);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function removerItem(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         carrinho = carrinho.filter(p => p.id !== id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             function abrirCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     document.getElementById("modalCarrinho").style.display = "flex";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function fecharCarrinho() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         document.getElementById("modalCarrinho").style.display = "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         function finalizarCompra() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (carrinho.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     alert("Adicione produtos ao carrinho primeiro!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const total = carrinho.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             (soma, p) => soma + p.preco * p.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const pedido = carrinho.map(p =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             `${p.nome} - ${p.quantidade} unidade(s) - ${moeda(p.preco * p.quantidade)}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ).join("\n");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const mensagem = `Olá! Gostaria de fazer este pedido:\n\n${pedido}\n\nTotal: ${moeda(total)}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         alert("Pedido preparado! Para receber pedidos reais, configure o WhatsApp da loja.");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const numeroLoja = ""; // Coloque o número com DDD, somente números.

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (!/^\d{10,13}$/.test(numeroLoja)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         alert("A loja ainda não configurou o número de WhatsApp.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         window.open(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 `https://wa.me/55${numeroLoja}?text=${encodeURIComponent(mensagem)}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         "_blank"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             mostrarProdutos(produtos);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             atualizarCarrinho();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             